using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments =
    [
        new() { Id = 1, Name = "Computer Science", Code = "CS" },
        new() { Id = 2, Name = "Mathematics", Code = "MATH" },
        new() { Id = 3, Name = "Physics", Code = "PHYS" },
        new() { Id = 4, Name = "English", Code = "ENG" },
        new() { Id = 5, Name = "History", Code = "HIST" },
    ];

    private readonly List<Course> _courses =
    [
        new() { Id = 1, Code = "CS 101", Title = "Introduction to Programming", Description = "Learn the fundamentals of programming using C#. Topics include variables, control flow, loops, methods, and object-oriented design principles.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", InstructorName = "Dr. Sarah Chen", InstructorBio = "Dr. Chen has 15 years of experience in software engineering and computer science education. She holds a PhD from MIT and has published extensively on programming pedagogy.", DepartmentId = 1, IsFeatured = true },
        new() { Id = 2, Code = "CS 201", Title = "Data Structures and Algorithms", Description = "Study fundamental data structures (arrays, linked lists, trees, graphs) and algorithm design techniques (sorting, searching, dynamic programming).", Credits = 4, Schedule = "Tue/Thu 10:30–11:45 AM", InstructorName = "Dr. James Park", InstructorBio = "Dr. Park specializes in algorithm design and computational complexity. Previously a software architect at a major tech company, he brings industry experience to the classroom.", DepartmentId = 1, IsFeatured = true },
        new() { Id = 3, Code = "CS 310", Title = "Database Systems", Description = "Introduction to relational database design, SQL, normalization, transaction processing, and modern NoSQL approaches.", Credits = 3, Schedule = "Mon/Wed 2:00–3:15 PM", InstructorName = "Dr. Maria Rodriguez", InstructorBio = "Dr. Rodriguez is a database researcher with expertise in distributed systems. She has contributed to several open-source database projects.", DepartmentId = 1, IsFeatured = false },
        new() { Id = 4, Code = "MATH 151", Title = "Calculus I", Description = "Limits, derivatives, and integrals of single-variable functions. Applications to physics, engineering, and economics.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", InstructorName = "Dr. Robert Kim", InstructorBio = "Dr. Kim is an award-winning mathematics educator who has been teaching calculus for over 20 years. He is known for making complex concepts accessible.", DepartmentId = 2, IsFeatured = true },
        new() { Id = 5, Code = "MATH 252", Title = "Linear Algebra", Description = "Vector spaces, matrices, linear transformations, eigenvalues, and applications to data science and engineering.", Credits = 3, Schedule = "Tue/Thu 1:00–2:15 PM", InstructorName = "Dr. Lisa Wang", InstructorBio = "Dr. Wang researches applications of linear algebra in machine learning. She holds joint appointments in Mathematics and Computer Science.", DepartmentId = 2, IsFeatured = false },
        new() { Id = 6, Code = "PHYS 101", Title = "General Physics I", Description = "Mechanics, thermodynamics, and waves. Includes laboratory component with hands-on experiments.", Credits = 4, Schedule = "Mon/Wed/Fri 11:00–11:50 AM + Lab Thu 2:00–4:50 PM", InstructorName = "Dr. Alan Foster", InstructorBio = "Dr. Foster is an experimental physicist whose research focuses on condensed matter physics. He emphasizes connecting theory to real-world phenomena.", DepartmentId = 3, IsFeatured = false },
        new() { Id = 7, Code = "PHYS 201", Title = "Electromagnetism", Description = "Electric fields, magnetic fields, Maxwell's equations, electromagnetic waves, and optics.", Credits = 4, Schedule = "Tue/Thu 9:00–10:15 AM + Lab Fri 1:00–3:50 PM", InstructorName = "Dr. Nina Patel", InstructorBio = "Dr. Patel is a theoretical physicist specializing in quantum electrodynamics. She has received multiple teaching excellence awards.", DepartmentId = 3, IsFeatured = true },
        new() { Id = 8, Code = "ENG 110", Title = "Academic Writing", Description = "Develop skills in analytical reading, critical thinking, and clear academic writing. Emphasis on argumentation and research-based essays.", Credits = 3, Schedule = "Mon/Wed 9:00–10:15 AM", InstructorName = "Prof. David Miller", InstructorBio = "Prof. Miller is a published author and writing instructor with expertise in rhetoric and composition. He has mentored hundreds of students in academic writing.", DepartmentId = 4, IsFeatured = false },
        new() { Id = 9, Code = "ENG 250", Title = "American Literature", Description = "Survey of major works in American literature from the colonial period to the present, exploring themes of identity, freedom, and social change.", Credits = 3, Schedule = "Tue/Thu 11:00 AM–12:15 PM", InstructorName = "Dr. Angela Thompson", InstructorBio = "Dr. Thompson is a literary scholar specializing in 20th-century American fiction. Her recent book examines narratives of migration in contemporary literature.", DepartmentId = 4, IsFeatured = false },
        new() { Id = 10, Code = "HIST 101", Title = "World History to 1500", Description = "Survey of major civilizations, cultural exchanges, and transformative events from prehistory through the late medieval period.", Credits = 3, Schedule = "Mon/Wed/Fri 1:00–1:50 PM", InstructorName = "Dr. Michael Torres", InstructorBio = "Dr. Torres is a historian of the ancient and medieval world with archaeological fieldwork experience across three continents.", DepartmentId = 5, IsFeatured = false },
        new() { Id = 11, Code = "HIST 220", Title = "Modern European History", Description = "Political, social, and cultural developments in Europe from the Enlightenment through the 21st century.", Credits = 3, Schedule = "Tue/Thu 2:30–3:45 PM", InstructorName = "Dr. Catherine Hayes", InstructorBio = "Dr. Hayes specializes in modern European intellectual history. She spent a decade researching in European archives before joining our faculty.", DepartmentId = 5, IsFeatured = true },
    ];

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetCourses(string? search = null, int? departmentId = null)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue)
            query = query.Where(c => c.DepartmentId == departmentId.Value);

        if (!string.IsNullOrWhiteSpace(search))
        {
            var term = search.Trim();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.InstructorName.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();
}

